'use client';

import { useState, useCallback } from 'react';
import type { ChartData } from '@/types';

interface InterpretationPanelProps {
  chart: ChartData;
}

type InterpretationSection = 'overview' | 'type' | 'authority' | 'channels' | 'cross';

interface SectionState {
  content: string;
  isLoading: boolean;
  isGenerated: boolean;
}

// Fallback interpretations when AI is unavailable
function getFallbackInterpretation(section: InterpretationSection, chart: ChartData): string {
  const fallbacks: Record<InterpretationSection, string> = {
    overview: `You are a ${chart.type} with ${chart.authority} Authority.

Your Strategy is to "${chart.strategy}" - this is the key to making correct decisions and attracting the right opportunities in life.

With a ${chart.profile} Profile and ${chart.definition} Definition, you have a unique way of learning and engaging with the world.

Your Incarnation Cross, the ${chart.cross.name}, represents your life's purpose and the unique contribution you're here to make.

Use the chat feature to ask specific questions about your design!`,

    type: `As a ${chart.type}, your Strategy is: ${chart.strategy}

When you're living correctly, you experience: ${chart.signature}
When out of alignment, you may feel: ${chart.not_self}

The key for you is to trust your natural way of operating in the world. Every Type has its unique genius - yours comes through ${chart.type === 'Generator' || chart.type === 'Manifesting Generator' ? 'your sustainable life force energy' : chart.type === 'Manifestor' ? 'your initiating power' : chart.type === 'Projector' ? 'your ability to guide and manage others' : 'your ability to reflect and evaluate'}.

Try the chat to explore more about how to honor your Type!`,

    authority: `Your Authority is ${chart.authority}.

This is your inner compass for making decisions. ${chart.authority === 'Emotional' ? 'Wait for emotional clarity before deciding - there is no truth in the now.' : chart.authority === 'Sacral' ? 'Trust your gut response - the "uh-huh" or "unh-unh" in the moment.' : chart.authority === 'Splenic' ? 'Trust your instant intuition - it speaks once, quietly.' : 'Trust your inner knowing and give yourself time to find clarity.'}

Your Authority is one of the most practical tools in Human Design. Ask questions in the chat to learn how to apply it!`,

    channels: `You have ${chart.channels.length} defined channel(s) in your chart.

Your circuitry balance:
- Individual: ${chart.circuitry.individual}% (mutation, uniqueness, empowerment)
- Tribal: ${chart.circuitry.tribal}% (support, resources, family)
- Collective: ${chart.circuitry.collective}% (sharing, logic, experience)

${chart.channels.map((c) => `• ${c.name} (${c.gates[0]}-${c.gates[1]})`).join('\n')}

Each channel represents consistent energy in your life. Use the chat to explore what each means!`,

    cross: `Your Incarnation Cross: ${chart.cross.name}
Type: ${chart.cross.type}
Quarter: ${chart.cross.quarter}

Gates: ${chart.cross.gates.join(', ')}

Your Incarnation Cross represents your life's purpose - the theme that unfolds as you live correctly according to your Type and Authority.

${chart.cross.type === 'Right Angle' ? 'As a Right Angle cross, your purpose is deeply personal.' : chart.cross.type === 'Left Angle' ? 'As a Left Angle cross, your purpose involves others and transpersonal karma.' : 'As a Juxtaposition cross, you have a fixed fate and specific life purpose.'}

Explore your Cross further through the chat!`,
  };

  return fallbacks[section];
}

export function InterpretationPanel({ chart }: InterpretationPanelProps) {
  const [activeSection, setActiveSection] = useState<InterpretationSection>('overview');
  const [sections, setSections] = useState<Record<InterpretationSection, SectionState>>({
    overview: { content: '', isLoading: false, isGenerated: false },
    type: { content: '', isLoading: false, isGenerated: false },
    authority: { content: '', isLoading: false, isGenerated: false },
    channels: { content: '', isLoading: false, isGenerated: false },
    cross: { content: '', isLoading: false, isGenerated: false },
  });

  const generateInterpretation = useCallback(async (section: InterpretationSection) => {
    if (sections[section].isGenerated) return;

    setSections((prev) => ({
      ...prev,
      [section]: { ...prev[section], isLoading: true },
    }));

    // For now, use fallback content (AI integration can be added when GOOGLE_GENERATIVE_AI_API_KEY is configured)
    // This provides immediate value while the full AI system is being set up
    const content = getFallbackInterpretation(section, chart);

    // Simulate slight delay for better UX
    await new Promise((resolve) => setTimeout(resolve, 500));

    setSections((prev) => ({
      ...prev,
      [section]: { content, isLoading: false, isGenerated: true },
    }));
  }, [chart, sections]);

  const sectionLabels: Record<InterpretationSection, string> = {
    overview: 'Overview',
    type: 'Type & Strategy',
    authority: 'Authority',
    channels: 'Channels',
    cross: 'Incarnation Cross',
  };

  return (
    <div className="space-y-6">
      {/* Section Navigation */}
      <div className="flex flex-wrap gap-2">
        {(Object.keys(sectionLabels) as InterpretationSection[]).map((section) => (
          <button
            key={section}
            onClick={() => setActiveSection(section)}
            className={`px-4 py-2 rounded-full text-sm font-mono uppercase tracking-wider transition-all ${
              activeSection === section
                ? 'bg-gradient-to-r from-solar-glow to-haze-pink text-white shadow-lg'
                : 'bg-white/5 text-white/70 hover:bg-white/10 hover:text-white'
            }`}
          >
            {sectionLabels[section]}
            {sections[section].isGenerated && (
              <span className="ml-2 text-xs">&#10003;</span>
            )}
          </button>
        ))}
      </div>

      {/* Content Area */}
      <div className="min-h-[300px] p-6 rounded-3xl bg-white/5 border border-white/10">
        {!sections[activeSection].isGenerated && !sections[activeSection].isLoading ? (
          <div className="flex flex-col items-center justify-center h-full min-h-[200px] text-center">
            <p className="text-white/60 mb-4">
              COMING SOON: Generate an interpretation of your {sectionLabels[activeSection].toLowerCase()}
            </p>
            <button
              onClick={() => generateInterpretation(activeSection)}
              className="solar-button px-8 py-3"
            >
              Generate Reading
            </button>
          </div>
        ) : sections[activeSection].isLoading ? (
          <div className="flex flex-col items-center justify-center h-full min-h-[200px]">
            <div className="w-8 h-8 border-2 border-solar-glow border-t-transparent rounded-full animate-spin mb-4" />
            <p className="text-black/60 font-mono text-sm uppercase tracking-wider">
              Generating interpretation...
            </p>
          </div>
        ) : (
          <div className="prose prose-invert max-w-none">
            <div className="text-white/90 leading-relaxed whitespace-pre-wrap">
              {sections[activeSection].content}Coming soon...
            </div>
          </div>
        )}
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="p-4 rounded-2xl bg-white/5 text-center">
          <div className="text-xs font-mono text-solar-glow uppercase tracking-wider mb-1">
            Type
          </div>
          <div className="text-white font-medium">{chart.type}</div>
        </div>
        <div className="p-4 rounded-2xl bg-white/5 text-center">
          <div className="text-xs font-mono text-solar-glow uppercase tracking-wider mb-1">
            Authority
          </div>
          <div className="text-white font-medium">{chart.authority}</div>
        </div>
        <div className="p-4 rounded-2xl bg-white/5 text-center">
          <div className="text-xs font-mono text-solar-glow uppercase tracking-wider mb-1">
            Profile
          </div>
          <div className="text-white font-medium">{chart.profile}</div>
        </div>
        <div className="p-4 rounded-2xl bg-white/5 text-center">
          <div className="text-xs font-mono text-solar-glow uppercase tracking-wider mb-1">
            Definition
          </div>
          <div className="text-white font-medium">{chart.definition}</div>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// CORE CHART TYPES
// ============================================================================

export type HumanDesignType = 
  | 'Manifestor' 
  | 'Generator' 
  | 'Manifesting Generator' 
  | 'Projector' 
  | 'Reflector';

export type Strategy = 
  | 'Inform' 
  | 'Wait to Respond' 
  | 'Wait for Invitation' 
  | 'Wait Lunar Cycle';

export type Authority = 
  | 'Emotional' 
  | 'Sacral' 
  | 'Splenic' 
  | 'Ego' 
  | 'Self-Projected' 
  | 'Mental' 
  | 'Lunar';

export type Definition = 
  | 'None' 
  | 'Single' 
  | 'Split' 
  | 'Triple Split' 
  | 'Quadruple Split';

export type CrossType = 
  | 'Right Angle' 
  | 'Juxtaposition' 
  | 'Left Angle';

export type Quarter = 
  | 'Initiation' 
  | 'Civilization' 
  | 'Duality' 
  | 'Mutation';

export type Circuit = 
  | 'Individual' 
  | 'Tribal' 
  | 'Collective';

export type CenterName = 
  | 'head' 
  | 'ajna' 
  | 'throat' 
  | 'g' 
  | 'ego' 
  | 'sacral' 
  | 'solar_plexus' 
  | 'spleen' 
  | 'root';

export type Planet = 
  | 'sun' 
  | 'earth' 
  | 'north_node' 
  | 'south_node' 
  | 'moon' 
  | 'mercury' 
  | 'venus' 
  | 'mars' 
  | 'jupiter' 
  | 'saturn' 
  | 'uranus' 
  | 'neptune' 
  | 'pluto';

// ============================================================================
// DATA STRUCTURES
// ============================================================================

export interface Activation {
  gate: number;
  line: number;
}

export interface Activations {
  sun: Activation;
  earth: Activation;
  north_node: Activation;
  south_node: Activation;
  moon: Activation;
  mercury: Activation;
  venus: Activation;
  mars: Activation;
  jupiter: Activation;
  saturn: Activation;
  uranus: Activation;
  neptune: Activation;
  pluto: Activation;
}

export interface Center {
  defined: boolean;
  gates: number[];
}

export interface Channel {
  gates: [number, number];
  name: string;
  circuit: Circuit;
  stream: string;
}

export interface Cross {
  name: string;
  type: CrossType;
  quarter: Quarter;
  gates: [number, number, number, number];
}

export interface GateInfo {
  name: string;
  center: CenterName;
}

export interface Circuitry {
  individual: number;
  tribal: number;
  collective: number;
}

// ============================================================================
// CHART OBJECT
// ============================================================================

export interface ChartData {
  type: HumanDesignType;
  strategy: Strategy;
  signature: string;
  not_self: string;
  authority: Authority;
  profile: string;
  definition: Definition;
  cross: Cross;
  centers: Record<CenterName, Center>;
  channels: Channel[];
  activations: {
    personality: Activations;
    design: Activations;
  };
  gates: Record<string, GateInfo>;
  circuitry: Circuitry;
}

export interface BirthData {
  datetime_utc: string;
  timezone: string;
  lat: number;
  lng: number;
}

export interface ChartResponse {
  birth: BirthData;
  chart: ChartData;
  reference?: ReferenceData;
}

// ============================================================================
// REFERENCE DATA
// ============================================================================

export interface GateReference {
  id: number;
  name: string;
  center: CenterName;
  keynotes?: string;
  description?: string;
  shadow?: string;
  gift?: string;
  siddhi?: string;
}

export interface ChannelReference {
  id: string;
  gates: [number, number];
  name: string;
  circuit: Circuit;
  stream: string;
  description?: string;
}

export interface TypeReference {
  id: HumanDesignType;
  strategy: Strategy;
  signature: string;
  not_self: string;
  description?: string;
}

export interface AuthorityReference {
  id: Authority;
  name: string;
  center?: CenterName;
  description?: string;
}

export interface ProfileReference {
  id: string;
  conscious_line: number;
  unconscious_line: number;
  name?: string;
  description?: string;
}

export interface ReferenceData {
  type?: TypeReference;
  authority?: AuthorityReference;
  profile?: ProfileReference;
  channels?: Record<string, ChannelReference>;
  gates?: Record<string, GateReference>;
}

// ============================================================================
// API TYPES
// ============================================================================

export interface CalculateChartRequest {
  datetime_utc: string;
  lat: number;
  lng: number;
}

export interface CalculateTransitRequest {
  datetime_utc?: string; // Defaults to now
  lat?: number;
  lng?: number;
}

export interface CalculateCompositeRequest {
  chart_a: CalculateChartRequest;
  chart_b: CalculateChartRequest;
}

export interface CompositeResponse {
  chart_a: ChartData;
  chart_b: ChartData;
  analysis: {
    electromagnetic: Channel[];
    compromise_gates: number[];
    dominance_gates: number[];
    shared_channels: Channel[];
    combined_channels: Channel[];
    combined_definition: Definition;
    companionship_analysis: {
      electromagnetic_count: number;
      shared_channel_count: number;
      dominance_gate_count: number;
      compatibility_score: number;
    };
  };
}

// ============================================================================
// UI TYPES
// ============================================================================

export type SelectedElement =
  | { type: 'center'; name: CenterName; defined: boolean }
  | { type: 'gate'; number: number; center: CenterName }
  | { type: 'channel'; gates: [number, number]; name: string; circuit: string };

export { calculateChartToolDefinition, executeCalculateChart } from './calculate-chart';
export { getGateInfoToolDefinition, executeGetGateInfo } from './get-gate-info';
export { getChannelInfoToolDefinition, executeGetChannelInfo, getAllChannels } from './get-channel-info';
export { getCurrentTransitToolDefinition, executeGetCurrentTransit } from './get-transit';

import type { Metadata } from 'next';
import { Outfit, DM_Serif_Display, JetBrains_Mono } from 'next/font/google';
import { CopilotKit } from '@copilotkit/react-core';
import './globals.css';

const outfit = Outfit({
  subsets: ['latin'],
  variable: '--font-outfit',
  weight: ['300', '500'],
});

const dmSerif = DM_Serif_Display({
  weight: ['400'],
  subsets: ['latin'],
  variable: '--font-dm-serif',
});

const jetbrainsMono = JetBrains_Mono({
  subsets: ['latin'],
  variable: '--font-jetbrains',
  weight: ['400', '500'],
});

export const metadata: Metadata = {
  title: 'Human Design Chart Calculator',
  description: 'Calculate your unique Human Design chart from your birth data',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body className={`${outfit.variable} ${dmSerif.variable} ${jetbrainsMono.variable} font-sans`}>
        <CopilotKit runtimeUrl="/api/copilotkit">
          {children}
        </CopilotKit>
      </body>
    </html>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useCopilotReadable } from '@copilotkit/react-core';
import { CopilotChat as CopilotChatUI } from '@copilotkit/react-ui';
import '@copilotkit/react-ui/styles.css';
import type { ChartData } from '@/types';

interface CopilotChatProps {
  chart?: ChartData | null;
}

export function CopilotChat({ chart }: CopilotChatProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [mounted, setMounted] = useState(false);

  // Ensure client-side only rendering
  useEffect(() => {
    setMounted(true);
  }, []);

  // Provide chart context to CopilotKit
  useCopilotReadable({
    description: "The user's complete Human Design chart data including type, authority, profile, centers, gates, channels, and incarnation cross",
    value: chart,
  });

  if (!mounted) return null;

  return (
    <>
      {/* Chat Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-6 right-6 z-50 w-14 h-14 rounded-full flex items-center justify-center transition-all duration-300 shadow-lg hover:scale-105"
        style={{
          background: 'linear-gradient(135deg, #ff9d6c, #f0a2b1)',
          boxShadow:
            '0 8px 30px rgba(255, 157, 108, 0.4), 0 4px 15px rgba(240, 162, 177, 0.3)',
        }}
        aria-label={isOpen ? 'Close chat' : 'Open chat'}
      >
        {isOpen ? (
          <svg
            className="w-6 h-6 text-white"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        ) : (
          <svg
            className="w-6 h-6 text-white"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"
            />
          </svg>
        )}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div
          className="fixed bottom-24 right-6 z-50 w-[380px] h-[500px] rounded-3xl overflow-hidden flex flex-col copilot-chat-container"
          style={{
            background: 'rgba(13, 7, 26, 0.95)',
            backdropFilter: 'blur(20px)',
            border: '1px solid rgba(255, 157, 108, 0.2)',
            boxShadow:
              '0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 40px rgba(255, 157, 108, 0.15)',
          }}
        >
          {/* Header */}
          <div className="px-5 py-4 border-b border-white/10 flex-shrink-0">
            <h3 className="font-mono text-xs uppercase tracking-widest text-solar-glow">
              HD Guide
            </h3>
            <p className="text-white/50 text-xs mt-1">
              {chart
                ? `${chart.type} • ${chart.authority}`
                : 'Calculate your chart first'}
            </p>
          </div>

          {/* CopilotKit Chat UI */}
          <div className="flex-1 overflow-hidden">
            <CopilotChatUI
              labels={{
                initial: chart
                  ? `Hello! I see you're a ${chart.type} with ${chart.authority} Authority. I'm here to help you understand your Human Design chart. What would you like to know?`
                  : 'Please calculate your chart first to get personalized guidance.',
                placeholder: chart
                  ? 'Ask about your chart...'
                  : 'Calculate your chart first',
              }}
              className="h-full copilot-chat-inner"
            />
          </div>
        </div>
      )}

      {/* Custom styles for CopilotKit UI */}
      <style jsx global>{`
        .copilot-chat-container .copilot-chat-inner {
          background: transparent !important;
          height: 100% !important;
        }

        .copilot-chat-container [class*="copilotkit"] {
          background: transparent !important;
          font-family: var(--font-outfit), sans-serif !important;
        }

        .copilot-chat-container [class*="messages"] {
          background: transparent !important;
          padding: 1rem !important;
        }

        .copilot-chat-container [class*="message"] {
          background: rgba(255, 255, 255, 0.05) !important;
          border: 1px solid rgba(255, 255, 255, 0.1) !important;
          border-radius: 1rem !important;
          color: rgba(255, 255, 255, 0.9) !important;
        }

        .copilot-chat-container [class*="user"] [class*="message"] {
          background: linear-gradient(135deg, rgba(255, 157, 108, 0.2), rgba(240, 162, 177, 0.15)) !important;
          border: 1px solid rgba(255, 157, 108, 0.3) !important;
        }

        .copilot-chat-container [class*="input"] {
          background: rgba(255, 255, 255, 0.05) !important;
          border: 1px solid rgba(255, 255, 255, 0.1) !important;
          border-radius: 9999px !important;
          color: white !important;
          padding: 0.5rem 1rem !important;
        }

        .copilot-chat-container [class*="input"]::placeholder {
          color: rgba(255, 255, 255, 0.4) !important;
        }

        .copilot-chat-container [class*="input"]:focus {
          border-color: rgba(255, 157, 108, 0.5) !important;
          outline: none !important;
        }

        .copilot-chat-container button[type="submit"],
        .copilot-chat-container [class*="send"] {
          background: linear-gradient(135deg, #ff9d6c, #f0a2b1) !important;
          border-radius: 9999px !important;
          color: white !important;
        }

        .copilot-chat-container [class*="header"] {
          display: none !important;
        }

        .copilot-chat-container [class*="footer"] {
          background: transparent !important;
          border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
          padding: 0.75rem !important;
        }
      `}</style>
    </>
  );
}

import {
  CopilotRuntime,
  GoogleGenerativeAIAdapter,
  copilotRuntimeNextJSAppRouterEndpoint,
} from '@copilotkit/runtime';
import { NextRequest } from 'next/server';
import {
  executeCalculateChart,
  executeGetGateInfo,
  executeGetChannelInfo,
  executeGetCurrentTransit,
} from '@/lib/agents/tools';

const serviceAdapter = new GoogleGenerativeAIAdapter({
  model: 'gemini-3-flash-preview',
});

export async function POST(req: NextRequest) {
  const runtime = new CopilotRuntime({
    actions: [
      {
        name: 'calculateChart',
        description: 'Calculate a Human Design chart from birth data. Returns complete chart including type, strategy, authority, profile, centers, channels, and activations.',
        parameters: [
          {
            name: 'datetime_utc',
            type: 'string',
            description: 'Birth datetime in UTC ISO format (e.g., "1990-01-15T14:30:00Z")',
            required: true,
          },
          {
            name: 'lat',
            type: 'number',
            description: 'Birth location latitude',
            required: true,
          },
          {
            name: 'lng',
            type: 'number',
            description: 'Birth location longitude',
            required: true,
          },
        ],
        handler: async (args: { datetime_utc: string; lat: number; lng: number }) => {
          return executeCalculateChart(args);
        },
      },
      {
        name: 'getGateInfo',
        description: 'Get detailed information about a specific Human Design gate, including its name, center location, and keynotes.',
        parameters: [
          {
            name: 'gate_id',
            type: 'number',
            description: 'The gate number (1-64)',
            required: true,
          },
        ],
        handler: async (args: { gate_id: number }) => {
          return executeGetGateInfo(args);
        },
      },
      {
        name: 'getChannelInfo',
        description: 'Get detailed information about a Human Design channel by its gates or name. Returns circuit, stream, and thematic meaning.',
        parameters: [
          {
            name: 'gate_a',
            type: 'number',
            description: 'First gate of the channel',
            required: false,
          },
          {
            name: 'gate_b',
            type: 'number',
            description: 'Second gate of the channel',
            required: false,
          },
          {
            name: 'channel_id',
            type: 'string',
            description: 'Channel ID in format "gate1-gate2" (e.g., "12-22")',
            required: false,
          },
        ],
        handler: async (args: { gate_a?: number; gate_b?: number; channel_id?: string }) => {
          return executeGetChannelInfo(args);
        },
      },
      {
        name: 'getCurrentTransit',
        description: 'Get the current Human Design transit (planetary activations) for right now or a specific datetime. Shows which gates are activated by current planetary positions.',
        parameters: [
          {
            name: 'datetime_utc',
            type: 'string',
            description: 'Optional datetime in UTC ISO format. Defaults to current moment if not provided.',
            required: false,
          },
        ],
        handler: async (args: { datetime_utc?: string }) => {
          return executeGetCurrentTransit(args);
        },
      },
    ],
  });

  const { handleRequest } = copilotRuntimeNextJSAppRouterEndpoint({
    runtime,
    serviceAdapter,
    endpoint: '/api/copilotkit',
  });

  return handleRequest(req);
}

import { z } from 'zod';

// Gate reference data - 64 gates with their centers and descriptions
const GATES: Record<number, { name: string; center: string; keynote: string }> = {
  1: { name: 'Self-Expression', center: 'g', keynote: 'The gate of creative self-expression and individuality' },
  2: { name: 'Direction of Self', center: 'g', keynote: 'The gate of the receptive, allowing life to unfold' },
  3: { name: 'Ordering', center: 'sacral', keynote: 'The gate of mutation and new beginnings' },
  4: { name: 'Formulization', center: 'ajna', keynote: 'The gate of mental answers and formulas' },
  5: { name: 'Waiting', center: 'sacral', keynote: 'The gate of natural rhythms and patterns' },
