  const isLoading = copilotChat?.isLoading ?? false;
  const appendMessage = copilotChat?.appendMessage;

  // Share chart context with CopilotKit
  useCopilotReadable({
    description: "User's Human Design chart for interpretation",
    value: chart,
  });

  // Save sections whenever they change
  useEffect(() => {
    saveSections(sections);
  }, [sections]);

  // Watch for AI response completion
  useEffect(() => {
    if (!pendingSection) return;
    if (isLoading) return;

    // Check if we have new messages
    const assistantMessages = visibleMessages.filter((m) => m.role === 'assistant');
    const lastMessage = assistantMessages[assistantMessages.length - 1];

    // Only process if we have a new message (after we sent our request)
    if (lastMessage && assistantMessages.length > messageCount) {
      const content = typeof lastMessage.content === 'string'
        ? lastMessage.content
        : '';

      if (content) {
        setSections((prev) => ({
          ...prev,
          [pendingSection]: {
            content,
            isLoading: false,
            isGenerated: true,
          },
        }));
        setPendingSection(null);
      }
    }
  }, [visibleMessages, isLoading, pendingSection, messageCount]);

  const generateInterpretation = useCallback(async (section: InterpretationSection) => {
    if (sections[section].isGenerated) return;

    // Set loading state
    setSections((prev) => ({
      ...prev,
      [section]: { ...prev[section], isLoading: true },
    }));

    try {
      // Check if CopilotKit is available
      if (!appendMessage) {
        throw new Error('CopilotKit not available');
      }

      // Track current message count before sending
      const currentAssistantCount = visibleMessages.filter((m) => m.role === 'assistant').length;
      setMessageCount(currentAssistantCount);
      setPendingSection(section);

      // Build the prompt and send to AI
      const prompt = buildSectionPrompt(section, chart);
      await appendMessage(
        new TextMessage({
          role: MessageRole.User,
          content: prompt,
        })
      );
    } catch (error) {
      console.error('Error generating interpretation:', error);
      // Fall back to static content on error
      const content = getFallbackInterpretation(section, chart);
      setSections((prev) => ({
        ...prev,
        [section]: { content, isLoading: false, isGenerated: true },
      }));
      setPendingSection(null);
    }
  }, [chart, sections, appendMessage, visibleMessages.length]);

  // Handle timeout - if loading takes too long, use fallback
  useEffect(() => {
    if (!pendingSection || !sections[pendingSection].isLoading) return;

    const timeout = setTimeout(() => {
      // If still loading after 30 seconds, use fallback
      if (pendingSection && sections[pendingSection].isLoading) {
        const content = getFallbackInterpretation(pendingSection, chart);
        setSections((prev) => ({
          ...prev,
          [pendingSection]: { content, isLoading: false, isGenerated: true },
        }));
        setPendingSection(null);
      }
    }, 30000);

    return () => clearTimeout(timeout);
  }, [pendingSection, sections, chart]);

  const sectionLabels: Record<InterpretationSection, string> = {
    overview: 'Overview',
    type: 'Type & Strategy',
    authority: 'Authority',
    channels: 'Channels',
    cross: 'Incarnation Cross',
  };

  return (
    <div className="space-y-6">
      {/* Section Navigation */}
      <div className="flex flex-wrap gap-2">
        {(Object.keys(sectionLabels) as InterpretationSection[]).map((section) => (
          <button
            key={section}
            onClick={() => setActiveSection(section)}
            className={`px-4 py-2 rounded-full text-sm font-mono uppercase tracking-wider transition-all ${
              activeSection === section
                ? 'bg-gradient-to-r from-solar-glow to-haze-pink text-white shadow-lg'
                : 'bg-white/5 text-white/70 hover:bg-white/10 hover:text-white'
            }`}
          >
            {sectionLabels[section]}
            {sections[section].isGenerated && (
              <span className="ml-2 text-xs">&#10003;</span>
            )}
          </button>
        ))}
      </div>

      {/* Content Area */}
      <div className="min-h-[300px] p-6 rounded-3xl bg-white/5 border border-white/10">
        {!sections[activeSection].isGenerated && !sections[activeSection].isLoading ? (
          <div className="flex flex-col items-center justify-center h-full min-h-[200px] text-center">
            <p className="text-white/60 mb-4">
              Generate an AI-powered interpretation of your {sectionLabels[activeSection].toLowerCase()}
            </p>
            <button
              onClick={() => generateInterpretation(activeSection)}
              className="solar-button px-8 py-3"
            >
              Generate Reading
            </button>
          </div>
        ) : sections[activeSection].isLoading ? (
