@@ -0,0 +1,86 @@
+/**
+ * In-memory LRU cache for API responses
+ * Reduces external API calls by caching results
+ */
+
+interface CacheEntry<T> {
+  value: T;
+  expiresAt: number;
+}
+
+export class LRUCache<T> {
+  private cache: Map<string, CacheEntry<T>> = new Map();
+  private readonly maxSize: number;
+  private readonly ttlMs: number;
+
+  constructor(maxSize: number, ttlMs: number) {
+    this.maxSize = maxSize;
+    this.ttlMs = ttlMs;
+  }
+
+  /**
+   * Get value from cache
+   * @param key - Cache key
+   * @returns Cached value or undefined if not found or expired
+   */
+  get(key: string): T | undefined {
+    const entry = this.cache.get(key);
+
+    if (!entry) {
+      return undefined;
+    }
+
+    // Check if expired
+    if (Date.now() >= entry.expiresAt) {
+      this.cache.delete(key);
+      return undefined;
+    }
+
+    // Move to end (mark as recently used)
+    this.cache.delete(key);
+    this.cache.set(key, entry);
+
+    return entry.value;
+  }
+
+  /**
+   * Set value in cache
+   * @param key - Cache key
+   * @param value - Value to cache
+   */
+  set(key: string, value: T): void {
+    // Remove if already exists (to re-add at end)
+    this.cache.delete(key);
+
+    // Evict oldest entry if at capacity
+    if (this.cache.size >= this.maxSize) {
+      const firstKey = this.cache.keys().next().value;
+      if (firstKey !== undefined) {
+        this.cache.delete(firstKey);
+      }
+    }
+
+    // Add new entry
+    this.cache.set(key, {
+      value,
+      expiresAt: Date.now() + this.ttlMs,
+    });
+  }
+
+  /**
+   * Clear all entries from cache
+   */
+  clear(): void {
+    this.cache.clear();
+  }
+
+  /**
+   * Get current cache size
+   */
+  get size(): number {
+    return this.cache.size;
+  }
+}
+
+// Geocoding cache: store up to 100 queries for 1 hour
+export const geocodingCache = new LRUCache<unknown>(100, 60 * 60 * 1000);

